package com.callguard;
import android.content.*;import android.security.keystore.*;import android.util.Base64;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
/** API session tokens are encrypted with a non-exportable Android Keystore key. */
final class SessionVault {
    private static SecretKey key() throws Exception {KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(store.containsAlias("callguard-session"))return (SecretKey)store.getKey("callguard-session",null);KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder("callguard-session",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return generator.generateKey();}
    static void save(Context context,String token,String userId,String email) throws Exception {Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());String value=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(token.getBytes(java.nio.charset.StandardCharsets.UTF_8)),Base64.NO_WRAP);context.getSharedPreferences("cloud",0).edit().clear().putString("session",value).putString("userId",userId).putString("email",email).apply();LicenseManager.clear(context);}
    static String token(Context context) throws Exception {String value=context.getSharedPreferences("cloud",0).getString("session","");if(value.isEmpty())return "";String[] parts=value.split(":");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));return new String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),java.nio.charset.StandardCharsets.UTF_8);}
    static String userId(Context context){return context.getSharedPreferences("cloud",0).getString("userId","");}
    static String email(Context context){return context.getSharedPreferences("cloud",0).getString("email","");}
    static void clear(Context context){context.getSharedPreferences("cloud",0).edit().clear().apply();LicenseManager.clear(context);}
}
